import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict(side, price, qty, seq)
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)

    for seq, o in enumerate(orders):
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            if oid in book:
                del book[oid]
            continue

        if typ in ('limit', 'ioc'):
            _, oid, side, price, qty = o
        else:  # market
            _, oid, side, qty = o
            price = None

        remaining = qty

        if side == 'buy':
            while remaining > 0 and sell_heap:
                p, s_seq, s_id = sell_heap[0]
                if s_id not in book:
                    heapq.heappop(sell_heap)
                    continue
                if typ != 'market' and p > price:
                    break
                resting = book[s_id]
                trade_qty = min(remaining, resting['qty'])
                trades.append([oid, s_id, p, trade_qty])
                remaining -= trade_qty
                resting['qty'] -= trade_qty
                if resting['qty'] == 0:
                    heapq.heappop(sell_heap)
                    del book[s_id]

            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'seq': seq}
                heapq.heappush(buy_heap, (-price, seq, oid))

        else:  # sell
            while remaining > 0 and buy_heap:
                negp, b_seq, b_id = buy_heap[0]
                if b_id not in book:
                    heapq.heappop(buy_heap)
                    continue
                p = -negp
                if typ != 'market' and p < price:
                    break
                resting = book[b_id]
                trade_qty = min(remaining, resting['qty'])
                trades.append([b_id, oid, p, trade_qty])
                remaining -= trade_qty
                resting['qty'] -= trade_qty
                if resting['qty'] == 0:
                    heapq.heappop(buy_heap)
                    del book[b_id]

            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'seq': seq}
                heapq.heappush(sell_heap, (price, seq, oid))

    return trades

